import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, time, sin, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    InstancedMesh,
    PlaneGeometry,
    IcosahedronGeometry,
    Object3D,
    Color,
    AdditiveBlending,
    PointLight,
  } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const palette = spec.colors ?? {};
  const bgHex = palette.background ?? '#0b0b10';
  const inkHex = palette.ink ?? '#16161d';
  const paperHex = palette.paper ?? '#e8ecf2';
  const accentHex = palette.accent ?? '#ff2a38';
  const stops = palette.gradientStops ?? [{ at: 0, hex: bgHex }, { at: 1, hex: inkHex }];

  const group = new Group();
  group.name = 'particle-constellation-hero';

  // ---------------------------------------------------------------
  // STAGE: backdrop gradient plane (7 x 6 at z = -2.5)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    color(stops[0].hex),
    color(stops[stops.length - 1].hex),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------------------------------------------------------------
  // FIELD PARTICLES: 1110 paper-tinted instanced icosahedra with
  // depth falloff baked into per-instance color (0.9 -> 0.15)
  // ---------------------------------------------------------------
  const FIELD_COUNT = 1110;
  const CORE_COUNT = 90;
  const particleGeo = new IcosahedronGeometry(0.012, 0);

  const fieldMat = new MeshBasicNodeMaterial();
  fieldMat.colorNode = color('#ffffff'); // modulated by instanceColor
  const fieldMesh = new InstancedMesh(particleGeo, fieldMat, FIELD_COUNT);

  const dummy = new Object3D();
  const paper = new Color(paperHex);
  const tint = new Color();
  const fieldAnchors = new Float32Array(FIELD_COUNT * 3);
  const fieldPhases = new Float32Array(FIELD_COUNT * 3);

  // ellipsoid 6 x 4 x 5 centered at [0, 0, -1.5] => semi-axes 3, 2, 2.5
  for (let i = 0; i < FIELD_COUNT; i++) {
    let x, y, z, r2;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
      r2 = x * x + y * y + z * z;
    } while (r2 > 1 || r2 < 0.04);
    const px = x * 3;
    const py = y * 2;
    const pz = z * 2.5 - 1.5;
    fieldAnchors[i * 3] = px;
    fieldAnchors[i * 3 + 1] = py;
    fieldAnchors[i * 3 + 2] = pz;
    fieldPhases[i * 3] = Math.random() * Math.PI * 2;
    fieldPhases[i * 3 + 1] = Math.random() * Math.PI * 2;
    fieldPhases[i * 3 + 2] = Math.random() * Math.PI * 2;

    dummy.position.set(px, py, pz);
    dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);

    // depth falloff: opacity 0.9 at z=0 linearly to 0.15 at z=-5
    const t = Math.min(Math.max(-pz / 5, 0), 1);
    const falloff = 0.9 + t * (0.15 - 0.9);
    tint.copy(paper).multiplyScalar(0.9 * falloff);
    fieldMesh.setColorAt(i, tint);
  }
  fieldMesh.instanceMatrix.needsUpdate = true;
  if (fieldMesh.instanceColor) fieldMesh.instanceColor.needsUpdate = true;
  group.add(fieldMesh);

  // ---------------------------------------------------------------
  // ACCENT CORE: 90 instances in 0.5-radius sphere, additive glow,
  // emissive pulse 1.5 -> 1.8 sine at 0.1 Hz (single brightest element)
  // ---------------------------------------------------------------
  const coreMat = new MeshBasicNodeMaterial();
  coreMat.colorNode = color(accentHex).mul(
    float(1.65).add(sin(time.mul(Math.PI * 2 * 0.1)).mul(0.15))
  );
  coreMat.transparent = true;
  coreMat.blending = AdditiveBlending;
  coreMat.depthWrite = false;

  const coreMesh = new InstancedMesh(particleGeo, coreMat, CORE_COUNT);
  const coreAnchors = new Float32Array(CORE_COUNT * 3);
  const corePhases = new Float32Array(CORE_COUNT * 3);

  for (let i = 0; i < CORE_COUNT; i++) {
    let x, y, z, r2;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
      r2 = x * x + y * y + z * z;
    } while (r2 > 1);
    const px = x * 0.5;
    const py = y * 0.5;
    const pz = z * 0.5;
    coreAnchors[i * 3] = px;
    coreAnchors[i * 3 + 1] = py;
    coreAnchors[i * 3 + 2] = pz;
    corePhases[i * 3] = Math.random() * Math.PI * 2;
    corePhases[i * 3 + 1] = Math.random() * Math.PI * 2;
    corePhases[i * 3 + 2] = Math.random() * Math.PI * 2;

    dummy.position.set(px, py, pz);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.setScalar(1.15);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  // node-local accent rim glow at the core (atmospheric, capped)
  const coreLight = new PointLight(new Color(accentHex), 1.2, 4.5, 2);
  coreLight.position.set(0, 0, 0.2);
  group.add(coreLight);

  // ---------------------------------------------------------------
  // AMBIENT DRIFT: +/-0.04 units at 0.05 Hz, offset phase per particle
  // ---------------------------------------------------------------
  const DRIFT_AMP = 0.04;
  const DRIFT_W = Math.PI * 2 * 0.05;
  let elapsed = 0;

  const tick = (_t, deltaMs) => {
    elapsed += (deltaMs ?? 16.6) / 1000;
    const wt = elapsed * DRIFT_W;

    for (let i = 0; i < FIELD_COUNT; i++) {
      const ix = i * 3;
      dummy.position.set(
        fieldAnchors[ix] + Math.sin(wt + fieldPhases[ix]) * DRIFT_AMP,
        fieldAnchors[ix + 1] + Math.sin(wt + fieldPhases[ix + 1]) * DRIFT_AMP,
        fieldAnchors[ix + 2] + Math.sin(wt + fieldPhases[ix + 2]) * DRIFT_AMP
      );
      dummy.rotation.set(fieldPhases[ix], fieldPhases[ix + 1], 0);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < CORE_COUNT; i++) {
      const ix = i * 3;
      dummy.position.set(
        coreAnchors[ix] + Math.sin(wt + corePhases[ix]) * DRIFT_AMP * 0.5,
        coreAnchors[ix + 1] + Math.sin(wt + corePhases[ix + 1]) * DRIFT_AMP * 0.5,
        coreAnchors[ix + 2] + Math.sin(wt + corePhases[ix + 2]) * DRIFT_AMP * 0.5
      );
      dummy.rotation.set(0, 0, 0);
      dummy.scale.setScalar(1.15);
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  };
  gsap.ticker.add(tick);

  // ---------------------------------------------------------------
  // TEXT: hero at z=0.5 / y=+0.5, subhead 0.75 below hero baseline,
  // caption at y=-2.25 (0.25-unit rhythm)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.5);
  group.add(textGroup);

  const layout = {
    hero: { y: 0.5, size: 124, color: paperHex, spacing: -1 },
    subhead: { y: -0.25, size: 40, color: paperHex, spacing: 1 },
    caption: { y: -2.25, size: 18, color: accentHex, spacing: 2 },
  };

  const textNodes = [];
  for (const item of items) {
    const role = item.role ?? 'body';
    const slot = layout[role] ?? { y: -1, size: 24, color: paperHex, spacing: 0 };
    const node = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? slot.size,
      color: slot.color,
      align: 'center',
      letterSpacingPx: slot.spacing,
    });
    node.position.set(0, slot.y, 0);
    textGroup.add(node);
    textNodes.push(node);
  }

  // ---------------------------------------------------------------
  // ENTRANCE: weighted rise-in for the type block (particles handled
  // by the particle-emerge primitive)
  // ---------------------------------------------------------------
  const introTl = gsap.timeline();
  introTl.from(textGroup.position, {
    y: -0.35,
    duration: 0.7,
    ease: 'power3.out',
  });
  introTl.fromTo(
    textGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.4
  );

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (applied via ctx, never inlined)
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[primitive.name];
    if (fn) primitiveHandles.push(fn(group, primitive.params));
  }

  // ---------------------------------------------------------------
  // HANDLERS + CLEANUP
  // ---------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    introTl.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
      if (h && h.timeline && typeof h.timeline.kill === 'function') h.timeline.kill();
    }
    for (const node of textNodes) {
      if (node.userData && typeof node.userData.cleanup === 'function') {
        node.userData.cleanup();
      }
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    particleGeo.dispose();
    fieldMat.dispose();
    coreMat.dispose();
    fieldMesh.dispose();
    coreMesh.dispose();
  };

  return group;
}
